import csv,numpy as np,sys
from collections import defaultdict
rows=list(csv.DictReader(open('../../responses.csv'))); p=np.load(sys.argv[1])
c=defaultdict(lambda:[0,0,0.0])
for r,pp in zip(rows,p):
    a=c[(r['number_set'],int(r['target']))]; a[0]+=1;a[1]+=int(r['rating']);a[2]+=pp
def ll(n,y,q): return y*np.log(q)+(n-y)*np.log(1-q)
S=defaultdict(float); T=defaultdict(list)
for (s,t),(n,y,pp) in c.items():
    q=pp/n; ph=np.clip(y/n,1e-3,1-1e-3); d=ll(n,y,ph)-ll(n,y,q); S[s]+=d; T[s].append((t,n,y,round(q,2)))
for s in sorted(S,key=lambda s:-S[s])[:25]:
    print(s,round(S[s],1)); 
    if len(sys.argv)>2: print('   ',sorted(T[s]))
